{
  "findings": [
    {
      "check_id": "CKV_AWS_21",
      "title": "Ensure all data stored in the S3 bucket have versioning enabled",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "MEDIUM",
      "explanation": "Versioning is not enabled on the S3 bucket, which increases the risk of data loss or corruption as previous versions of objects cannot be recovered."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "MEDIUM",
      "explanation": "Access logging is not enabled, which makes it difficult to track access patterns and detect unauthorized access to the bucket."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "Ensure that S3 buckets are encrypted with KMS by default",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have server-side encryption enabled, which could lead to sensitive data being stored in plaintext."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have a public access block configuration, which increases the risk of accidental public exposure of sensitive data."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket\" \"admin_dashboard\" {\n  bucket = \"smart-city-parking-management-system-s3-admin-dashboard-${random_string.bucket_suffix.result}\"\n\n  versioning {\n    enabled = true\n  }\n\n  logging {\n    target_bucket = \"log-bucket-name\" # Replace with the name of a dedicated logging bucket\n    target_prefix = \"admin-dashboard-logs/\"\n  }\n\n  server_side_encryption_configuration {\n    rule {\n      apply_server_side_encryption_by_default {\n        sse_algorithm     = \"aws:kms\"\n        kms_master_key_id = \"alias/aws/s3\" # Replace with your KMS key alias or ARN\n      }\n    }\n  }\n\n  public_access_block {\n    block_public_acls       = true\n    block_public_policy     = true\n    ignore_public_acls      = true\n    restrict_public_buckets = true\n  }\n}",
  "fix_summary": "Enabled versioning to protect against data loss, added access logging for monitoring, enforced server-side encryption with KMS for data protection, and configured a public access block to prevent accidental public exposure."
}
